This script reads `Raw!A:F` and `ParkMap!A:B`, then rebuilds `Clean` and `Final` without changing the source sheets.

One important distinction: **a duplicate flag doesn’t automatically mean `Review="REVIEW"`**. Otherwise, every repeated email would be excluded from `Final`. Matching copies can pass; conflicting copies go to review. `Final` keeps the most recent submission per email only if that submission is `OK`. It won’t silently substitute an older response if the newest one needs review.

```javascript
function runVolunteerCleaning() {
  const DATE_ORDER = 'MDY'; // Use 'DMY' if 3/4/21 means April 3.
  const WINDOW_MINUTES = 10;

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const tz = ss.getSpreadsheetTimeZone();
  const raw = ss.getSheetByName('Raw');
  const parkMap = ss.getSheetByName('ParkMap');
  if (!raw || !parkMap) throw new Error('Create Raw and ParkMap first.');

  const text = value => String(value ?? '').trim();
  const nameKey = value => text(value).toLowerCase().replace(/\s+/g, ' ');
  const parkKey = value => text(value).toLowerCase().replace(/[^a-z]/g, '');
  const months = 'jan feb mar apr may jun jul aug sep oct nov dec'.split(' ');
  const pad = n => String(n).padStart(2, '0');

  const parks = new Map();
  for (const [alias, canonical] of parkMap.getDataRange().getValues().slice(1)) {
    const key = parkKey(alias);
    const label = text(canonical);
    if (!key || !label) continue;
    if (parks.has(key) && parks.get(key) !== label) {
      throw new Error(`ParkMap has conflicting labels for "${alias}".`);
    }
    parks.set(key, label);
  }
  if (!parks.size) throw new Error('Add at least one alias and canonical name to ParkMap.');

  function parseTimestamp(value) {
    if (value instanceof Date && Number.isFinite(value.getTime())) return value;

    // Accept slash dates or day-Mon-year, with optional 24-hour time.
    const match = text(value).match(
      /^(\d{1,2}\/\d{1,2}\/(?:\d{4}|\d{2})|\d{1,2}-[a-z]{3}-\d{4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?$/i
    );
    if (!match) return null;

    let year, month, day;
    if (match[1].includes('/')) {
      const [a, b, y] = match[1].split('/');
      [month, day] = DATE_ORDER === 'MDY' ? [+a, +b] : [+b, +a];
      year = +y + (y.length === 2 ? 2000 : 0);
    } else {
      const [d, mon, y] = match[1].split('-');
      day = +d;
      month = months.indexOf(mon.toLowerCase()) + 1;
      year = +y;
    }

    const stamp = `${year}-${pad(month)}-${pad(day)} ` +
                  `${pad(+(match[2] || 0))}:${match[3] || '00'}:${match[4] || '00'}`;
    const format = 'yyyy-MM-dd HH:mm:ss';
    try {
      const date = Utilities.parseDate(stamp, tz, format);
      // Reject impossible dates or times rather than letting them roll over.
      return Utilities.formatDate(date, tz, format) === stamp ? date : null;
    } catch (err) {
      return null;
    }
  }

  const values = raw.getRange(1, 1, Math.max(1, raw.getLastRow()), 6).getValues();
  const rows = values.slice(1)
    .map((v, i) => ({ v, sourceRow: i + 2 }))
    .filter(r => r.v.some(value => text(value) !== ''))
    .map(r => {
      const [stamp, name, email, joined, phone, park] = r.v;
      const yn = text(joined).toLowerCase();
      const normalizedJoined = /^(y|yes)$/.test(yn) ? 'Yes'
                             : /^(n|no)$/.test(yn) ? 'No' : '';
      const digits = text(phone).replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
      const normalizedPhone = digits.length === 10 ? digits : '';
      const parsedTimestamp = parseTimestamp(stamp);
      const canonicalPark = parks.get(parkKey(park)) || '';
      const emailKey = text(email).toLowerCase();
      const normalizedName = nameKey(name);
      const reasons = new Set();

      if (!normalizedJoined) reasons.add('Unrecognized or missing Yes/No');
      if (!normalizedPhone) reasons.add('Phone needs a 10-digit number');
      if (!parsedTimestamp) reasons.add('Invalid or unrecognized timestamp');
      if (!canonicalPark) reasons.add('Unmapped or missing park');
      if (emailKey && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailKey)) {
        reasons.add('Check email format');
      }

      return {
        ...r, emailKey, normalizedName, normalizedJoined, normalizedPhone,
        parsedTimestamp, canonicalPark, reasons,
        dupEmail: '', dupNameTime: '', superseded: ''
      };
    });

  function groupBy(key) {
    const groups = new Map();
    for (const r of rows) {
      if (!r[key]) continue;
      if (!groups.has(r[key])) groups.set(r[key], []);
      groups.get(r[key]).push(r);
    }
    return groups;
  }

  const windowMs = WINDOW_MINUTES * 60 * 1000;
  for (const group of groupBy('normalizedName').values()) {
    for (let i = 0; i < group.length; i++) {
      const a = group[i];
      if (group.length > 1 && !a.emailKey) {
        a.reasons.add('Missing email and name appears more than once');
      }
      for (let j = i + 1; j < group.length; j++) {
        const b = group[j];
        if (!a.parsedTimestamp || !b.parsedTimestamp) continue;
        if (Math.abs(a.parsedTimestamp - b.parsedTimestamp) > windowMs) continue;
        a.dupNameTime = b.dupNameTime = 'DUP-name-time';
        if (!a.emailKey || !b.emailKey || a.emailKey !== b.emailKey) {
          a.reasons.add('Same name and close timestamp; email differs or is missing');
          b.reasons.add('Same name and close timestamp; email differs or is missing');
        }
      }
    }
  }

  const finalRows = [];
  for (const group of groupBy('emailKey').values()) {
    if (group.length > 1) {
      const signatures = new Set(group.map(r => JSON.stringify([
        r.normalizedName, r.normalizedJoined, r.normalizedPhone, r.canonicalPark
      ])));
      for (const r of group) {
        r.dupEmail = 'DUP-email';
        if (signatures.size > 1) r.reasons.add('Same email, conflicting name or answers');
      }
    }

    // An unreadable timestamp means we can't reliably identify the newest copy.
    if (group.some(r => !r.parsedTimestamp)) {
      if (group.length > 1) {
        group.forEach(r => r.reasons.add('Cannot order all submissions for this email'));
      }
      continue;
    }

    group.sort((a, b) =>
      b.parsedTimestamp - a.parsedTimestamp || b.sourceRow - a.sourceRow
    );
    group.slice(1).forEach(r => { r.superseded = 'SUPERSEDED'; });
    if (group[0].reasons.size === 0) finalRows.push(group[0]);
  }

  const headers = [
    'Timestamp', 'Name', 'Email', 'JoinedBefore', 'Phone', 'PreferredPark',
    'NormalizedJoined', 'NormalizedPhone', 'ParsedTimestamp', 'CanonicalPark',
    'DUP-email', 'DUP-name-time', 'SUPERSEDED', 'Review', 'ReviewReasons', 'RawRow'
  ];

  // Write imported strings as literal values, not formulas.
  const literal = value =>
    typeof value === 'string' && value.startsWith('=') ? "'" + value : value;

  function writeSheet(name, data) {
    const sheet = ss.getSheetByName(name) || ss.insertSheet(name);
    const output = [headers, ...data.map(r => [
      ...r.v, r.normalizedJoined, r.normalizedPhone, r.parsedTimestamp || '',
      r.canonicalPark, r.dupEmail, r.dupNameTime, r.superseded,
      r.reasons.size ? 'REVIEW' : 'OK', [...r.reasons].join('; '), r.sourceRow
    ].map(literal))];

    sheet.clearContents();
    if (sheet.getMaxRows() < output.length) {
      sheet.insertRowsAfter(sheet.getMaxRows(), output.length - sheet.getMaxRows());
    }
    if (sheet.getMaxColumns() < headers.length) {
      sheet.insertColumnsAfter(sheet.getMaxColumns(), headers.length - sheet.getMaxColumns());
    }
    if (data.length) {
      sheet.getRange(2, 5, data.length, 1).setNumberFormat('@');
      sheet.getRange(2, 8, data.length, 1).setNumberFormat('@');
      sheet.getRange(2, 1, data.length, 1).setNumberFormat('yyyy-mm-dd hh:mm:ss');
      sheet.getRange(2, 9, data.length, 1).setNumberFormat('yyyy-mm-dd hh:mm:ss');
    }
    sheet.getRange(1, 1, output.length, headers.length).setValues(output);
    sheet.setFrozenRows(1);
  }

  writeSheet('Clean', rows);
  writeSheet('Final', finalRows.sort((a, b) => a.sourceRow - b.sourceRow));
  ss.toast(`${rows.length} rows cleaned; ${finalRows.length} kept in Final.`);
}
```

### Install and run

1. Confirm `Raw` has headers in row 1 and survey data in columns A:F. In `ParkMap`, use column A for the alias and B for the canonical name, with headers in row 1. For example, `westside → West Side`, `wside → West Side`, and `northpark → North Park`.
2. Open **Extensions → Apps Script**, paste the code, and save. Select `runVolunteerCleaning`, click **Run**, and authorize it when prompted.
3. In `Clean`, filter `Review` to `REVIEW`. Use `ReviewReasons` and `RawRow` to find the source of each issue. Update `ParkMap` or correct verified source values, then rerun. **Each run replaces the contents of `Clean` and `Final`**, so don’t store review notes there.

A few details to check on the first run: equal timestamps are broken in favor of the later row in `Raw`; blank emails stay in `Clean` but don’t enter `Final`; and seven-digit phones are flagged rather than given a guessed area code. `DATE_ORDER` applies only to text dates—if Sheets already interpreted a date in the wrong order, the script can’t recover the original intent.

Set `keepMostRecent` and `WINDOW_MINUTES` at the top of the script. With `keepMostRecent = false`, the script selects the earliest submission by timestamp. In either mode, if the selected submission needs review, that email stays out of `Final`—the script doesn’t substitute another submission.

