      sheet.getRange(2, 1, count, 2).setNumberFormat('@');
      sheet.getRange(2, 3, count, 1).setNumberFormat('0');
    });
  ss.toast(`${rows.length} rows cleaned; ${finalRows.length} kept in Final.`);
}
