    });

  function groupBy(key) {
    const groups = new Map();
    for (const r of rows) {
      if (!r[key]) continue;
      if (!groups.has(r[key])) groups.set(r[key], []);
      groups.get(r[key]).push(r);
    }
    return groups;
  }

  const windowMs = WINDOW_MINUTES * 60 * 1000;
  for (const group of groupBy('normalizedName').values()) {
    for (let i = 0; i < group.length; i++) {
      const a = group[i];
      if (group.length > 1 && !a.emailKey) {
        a.reasons.add('Missing email and name appears more than once');
      }
      for (let j = i + 1; j < group.length; j++) {
        const b = group[j];
        if (!a.parsedTimestamp || !b.parsedTimestamp) continue;
        if (Math.abs(a.parsedTimestamp - b.parsedTimestamp) > windowMs) continue;
        a.dupNameTime = b.dupNameTime = 'DUP-name-time';
        if (!a.emailKey || !b.emailKey || a.emailKey !== b.emailKey) {
          a.reasons.add('Same name and close timestamp; email differs or is missing');
          b.reasons.add('Same name and close timestamp; email differs or is missing');
        }
      }
    }
  }

  const conflictFields = [
    ['Name', r => r.v[1]],
    ['JoinedBefore', r => r.v[3]],
    ['PhoneDigits', r => r.phoneDigits],
    ['PreferredParkRaw', r => r.preferredParkRaw],
    ['CanonicalPark', r => r.canonicalPark]
  ];

  const emailGroups = groupBy('emailKey');
  const finalRows = [];
  let emailDuplicates = 0;
  const direction = keepMostRecent ? -1 : 1;

  for (const group of emailGroups.values()) {
    if (group.length > 1) {
      emailDuplicates += group.length - 1;

      // Report differences in the output fields without changing review rules.
      const conflictSummary = conflictFields
        .filter(([, read]) => new Set(group.map(r => String(read(r) ?? ''))).size > 1)
        .map(([label]) => label)
        .join('; ');

      const signatures = new Set(group.map(r => JSON.stringify([
        r.normalizedName, r.normalizedJoined, r.phoneDigits, r.canonicalPark
      ])));

      for (const r of group) {
        r.dupEmail = 'DUP-email';
        r.conflictSummary = conflictSummary;
        if (signatures.size > 1) r.reasons.add('Same email, conflicting name or answers');
      }
    }

    if (group.some(r => !r.parsedTimestamp)) {
      if (group.length > 1) {
        group.forEach(r => r.reasons.add('Cannot order all submissions for this email'));
      }
      continue;
    }

    group.sort((a, b) => direction * (
      (a.parsedTimestamp - b.parsedTimestamp) || (a.sourceRow - b.sourceRow)
    ));
    group.slice(1).forEach(r => { r.superseded = 'SUPERSEDED'; });
    if (group[0].reasons.size === 0) finalRows.push(group[0]);
  }

  const headers = [
    'Timestamp', 'Name', 'Email', 'JoinedBefore', 'Phone', 'PreferredPark',
    'NormalizedJoined', 'NormalizedPhone', 'PhoneDigits', 'ParsedTimestamp',
    'PreferredParkRaw', 'CanonicalPark', 'DUP-email', 'DUP-name-time',
    'SUPERSEDED', 'Review', 'ReviewReasons', 'ConflictSummary', 'RawRow'
  ];

  // Prevent imported text beginning with "=" from becoming a formula.
  const literal = value =>
    typeof value === 'string' && value.startsWith('=') ? "'" + value : value;

  function writeSheet(name, output, applyFormats) {
    const sheet = ss.getSheetByName(name) || ss.insertSheet(name);
    const width = output[0].length;
    sheet.clearContents();
    if (sheet.getMaxRows() < output.length) {
      sheet.insertRowsAfter(sheet.getMaxRows(), output.length - sheet.getMaxRows());
    }
    if (sheet.getMaxColumns() < width) {
      sheet.insertColumnsAfter(sheet.getMaxColumns(), width - sheet.getMaxColumns());
    }
    if (applyFormats && output.length > 1) applyFormats(sheet, output.length - 1);
    sheet.getRange(1, 1, output.length, width).setValues(
      output.map(row => row.map(literal))
    );
    sheet.setFrozenRows(1);
  }

  function writeResponses(name, data) {
    writeSheet(name, [headers, ...data.map(r => [
      ...r.v, r.normalizedJoined, r.normalizedPhone, r.phoneDigits,
      r.parsedTimestamp || '', r.preferredParkRaw, r.canonicalPark,
      r.dupEmail, r.dupNameTime, r.superseded,
      r.reasons.size ? 'REVIEW' : 'OK', [...r.reasons].join('; '),
      r.conflictSummary, r.sourceRow
    ])], (sheet, count) => {
      for (const header of ['Phone', 'NormalizedPhone', 'PhoneDigits', 'PreferredParkRaw']) {
        sheet.getRange(2, headers.indexOf(header) + 1, count, 1).setNumberFormat('@');
      }
      for (const header of ['Timestamp', 'ParsedTimestamp']) {
        sheet.getRange(2, headers.indexOf(header) + 1, count, 1)
          .setNumberFormat('yyyy-mm-dd hh:mm:ss');
      }
    });
  }

  const candidateRows = [...candidates.entries()]
    .sort(([keyA, a], [keyB, b]) =>
      b.totalCount - a.totalCount || keyA.localeCompare(keyB))
    .map(([key, entry]) => [
      key,
      entry.totalCount,
      [...entry.variants.entries()]
        .sort(([valueA, countA], [valueB, countB]) =>
          countB - countA || valueA.localeCompare(valueB))
        .map(([original, count]) => `${original} (${count})`)
        .join('; ')
    ]);

  writeResponses('Clean', rows);
  writeResponses('Final', finalRows.sort((a, b) => a.sourceRow - b.sourceRow));
  writeSheet('ParkCandidates', [['key', 'totalCount', 'variants'], ...candidateRows],
    (sheet, count) => {
      sheet.getRange(2, 1, count, 1).setNumberFormat('@');
      sheet.getRange(2, 2, count, 1).setNumberFormat('0');
      sheet.getRange(2, 3, count, 1).setNumberFormat('@');
    });
  writeSheet('CleaningSummary', [
    ['Metric', 'Count'],
    ['Total rows processed', rows.length],
    ['Rows flagged REVIEW', rows.filter(r => r.reasons.size > 0).length],
    ['Unique emails', emailGroups.size],
    ['Email duplicates found', emailDuplicates],
    ['Final rows kept', finalRows.length],
    ['Park candidate keys', candidateRows.length]
  ], (sheet, count) => sheet.getRange(2, 2, count, 1).setNumberFormat('0'));

  ss.toast(`${rows.length} rows cleaned; ${finalRows.length} kept in Final.`);
}
```

**To run:** In **Extensions → Apps Script**, replace the previous script, save, and run `runVolunteerCleaning`. Each run rebuilds `Clean`, `Final`, `ParkCandidates`, and `CleaningSummary` without changing `Raw` or `ParkMap`.
